#include <bits/stdc++.h>
using namespace std;
struct Node{int mn,mx,mi,ma;};
int main(){ios::sync_with_stdio(false);cin.tie(nullptr);int n,m;cin>>n>>m;vector<int>a(n);for(int&x:a)cin>>x;int z=1;while(z<n)z*=2;vector<Node>t(2*z);for(int i=0;i<n;i++)t[z+i]={a[i],a[i],i,i};for(int i=z-1;i;i--){auto x=t[2*i],y=t[2*i+1];t[i]={min(x.mn,y.mn),max(x.mx,y.mx),x.mn<=y.mn?x.mi:y.mi,x.mx>=y.mx?x.ma:y.ma};}auto upd=[&](int p,int v){p+=z;a[p-z]=v;t[p]={v,v,p-z,p-z};for(p/=2;p;p/=2){auto x=t[2*p],y=t[2*p+1];t[p]={min(x.mn,y.mn),max(x.mx,y.mx),x.mn<=y.mn?x.mi:y.mi,x.mx>=y.mx?x.ma:y.ma};}};while(m--){int l,r;cin>>l>>r;--l;int L=l+z,R=r+z;Node left={INT_MAX,INT_MIN,0,0},right=left;while(L<R){if(L&1){auto x=t[L++];if(x.mn<left.mn){left.mn=x.mn;left.mi=x.mi;}if(x.mx>left.mx){left.mx=x.mx;left.ma=x.ma;}}if(R&1){auto x=t[--R];if(x.mn<right.mn){right.mn=x.mn;right.mi=x.mi;}if(x.mx>right.mx){right.mx=x.mx;right.ma=x.ma;}}L/=2;R/=2;}int p=left.mn<right.mn?left.mi:right.mi,q=left.mx>right.mx?left.ma:right.ma;int x=a[p],y=a[q];upd(p,y);upd(q,x);}for(int i=0;i<n;i++)cout<<a[i]<<" \n"[i+1==n];}
